<span class="line"><span style="color:#61AFEF;">sudo</span><span style="color:#98C379;"> apt-get</span><span style="color:#D19A66;"> -y</span><span style="color:#98C379;"> install</span><span style="color:#98C379;"> docker-ce</span></span>
